mapper.select:
SELECT B.BIZ_APP_MAP_ID AS BIZ_APP_MAP_ID, B.SYSTEM_ID AS SYSTEM_ID, B.DETAIL_CD AS DETAIL_CD,
       B.APP_ID AS APP_ID, B.ENV_CD AS ENV_CD, B.DOMAIN_CD AS DOMAIN_CD, B.BIZ_CD AS BIZ_CD,
       B.MAP_ROLE_CD AS MAP_ROLE_CD, B.PRIMARY_YN AS PRIMARY_YN, B.STATUS_CD AS STATUS_CD, B.REMARK AS REMARK,
       A.APP_NAME AS APP_NAME, A.APP_TYPE_CD AS APP_TYPE_CD,
       U.NAME_KO AS BIZ_NAME, U.NAME_EN AS BIZ_NAME_EN
  FROM TB_IF_BIZ_APP_MAP_PILOT B
  LEFT JOIN TB_IF_APPLICATION_PILOT A ON A.APP_ID = B.APP_ID
  LEFT JOIN TB_IF_BIZ_UNIT_PILOT U ON U.BIZ_CD = B.BIZ_CD
 WHERE 1=1
AND B.SYSTEM_ID = #{systemId}
AND B.DOMAIN_CD = #{domainCd}
AND B.ENV_CD = #{envCd}
AND B.BIZ_CD = #{bizCd}
AND B.APP_ID = #{appId}
 ORDER BY B.BIZ_CD, B.PRIMARY_YN DESC, B.APP_ID

SELECT B.BIZ_CD AS BIZ_CD, COUNT(*) AS APP_CNT,
       SUM(CASE WHEN B.STATUS_CD IN ('CONFIRMED','VALIDATED') THEN 1 ELSE 0 END) AS DONE_CNT,
       SUM(CASE WHEN B.STATUS_CD = 'DRAFT' THEN 1 ELSE 0 END) AS DRAFT_CNT
  FROM TB_IF_BIZ_APP_MAP_PILOT B
 WHERE 1=1
AND B.SYSTEM_ID = #{systemId}
AND B.DOMAIN_CD = #{domainCd}
AND B.ENV_CD = #{envCd}
 GROUP BY B.BIZ_CD

SELECT ASSET_ID AS ASSET_ID, ASSET_NAME AS ASSET_NAME, GROUP_ID AS GROUP_ID,
       TECH_ROLE_CD AS TECH_ROLE_CD, ENV_CD AS ENV_CD, STATUS_CD AS STATUS_CD
  FROM TB_IF_SERVER_ASSET_PILOT
 WHERE NVL(STATUS_CD,'') <> 'DELETED'
AND SYSTEM_ID = #{systemId}
AND ENV_CD = #{envCd}
AND TECH_ROLE_CD = #{techRoleCd}
 ORDER BY TECH_ROLE_CD, ASSET_ID

SELECT COUNT(*) FROM TB_IF_BIZ_APP_MAP_PILOT
 WHERE SYSTEM_ID = #{systemId} AND BIZ_CD = #{bizCd}
   AND APP_ID = #{appId} AND ENV_CD = #{envCd}

