SELECT G.GROUP_ID AS GROUP_ID, G.GROUP_NAME AS GROUP_NAME, G.SYSTEM_ID AS SYSTEM_ID, G.TECH_ROLE_CD AS TECH_ROLE_CD, G.ENV_CD AS ENV_CD, G.TIER_CD AS TIER_CD, G.STATUS_CD AS STATUS_CD, G.ACTIVE_NODES AS ACTIVE_NODES, G.STANDBY_NODES AS STANDBY_NODES, G.DR_NODES AS DR_NODES FROM TB_IF_SERVER_GROUP_PILOT G WHERE 1=1 AND G.SYSTEM_ID = #{systemId} AND G.ENV_CD = #{envCd} AND G.TECH_ROLE_CD = #{techRoleCd}
AND (UPPER(NVL(G.GROUP_ID,'')) LIKE '%'||UPPER(#{groupKeyword})||'%' OR UPPER(NVL(G.GROUP_NAME,'')) LIKE '%'||UPPER(#{groupKeyword})||'%')
ORDER BY G.TECH_ROLE_CD, G.GROUP_ID

